search-results.behavior:
document.querySelector("#search-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const query = e.target.querySelector("dads-search-box").value;
  // Fetch results and update the list
  console.log("Search:", query);
});

table-with-pagination.behavior:
document.querySelector("dads-page-navigation").addEventListener("page-change", (e) => {
  console.log("Page:", e.detail.page);
  // Fetch and render table rows for the new page
});

layout-master-detail.behavior:
// Master row click updates aside detail
document.querySelector("dads-table").addEventListener("row-select", (e) => {
  const aside = document.querySelector("dads-layout-aside");
  aside.textContent = "Selected: " + e.detail.id;
});

application-form-single-validation.behavior:
document.querySelector("#application-form-single").addEventListener("submit", (e) => {
  e.preventDefault();
  const form = e.target;
  let valid = true;
  form.querySelectorAll("[required]").forEach((el) => {
    if (!el.value) { el.setAttribute("error", ""); valid = false; }
    else { el.removeAttribute("error"); }
  });
  if (valid) console.log("Submit OK");
});

application-form-step-validation.behavior:
